function classifyActivity(a,chapter){const t=(a.title+' '+a.text).toLowerCase();if(chapter==='student')return a.kind==='student'||a.kind==='info'||a.kind==='life'||/award|school|exam|scholar|course|program|competition|olympiad|education/.test(t);if(chapter==='artist')return /art|paint|agar dress|creative|film|seed ball|design|illustrat|bioart|music|dance/.test(t);if(chapter==='researcher')return a.kind==='research'||/research|laboratory|phage|biology|cancer|genetic|clinical|intern|paper|publication/.test(t);if(chapter==='builder')return a.kind==='project'||/sugarcode|bionet|platform|module|software|startup|founder|entrepreneur|algorithm|model/.test(t);if(chapter==='writer')return a.kind==='writing'||/story|essay|chapter|mother|birth of|spectrum|alchemy|door/.test(t);if(chapter==='heritage')return /assam|tai-ahom|heritage|faa-sin|language|rural|grandmother|community/.test(t);return false}
function ActivityDossier({item,onClose}){return <div className="dossier-shell" role="dialog" aria-modal="true" aria-label={item.title}><button className="dossier-close" onClick={onClose} aria-label="Close activity"><X/></button><p className="eyebrow">{item.source} · embedded activity {item.id}</p><h2>{item.title}</h2><div className="dossier-body">{item.text.split(/\n+/).map((p,i)=><p key={i}>{p}</p>)}</div></div>}

const clueTrials={
 student:{title:'Light the syllabus',prompt:'The academy rewards curiosity, not rank. Touch the three constellations in the order a question becomes discovery.',choices:['wonder','test','share','answer'],sequence:['wonder','test','share'],success:'The tower opens a moonlit margin.'},
 artist:{title:'Grow an impossible pigment',prompt:'Mix the materials Udita uses to make science inhabitable. One ingredient is only decoration.',choices:['agar','neon pastel','living seed','perfect symmetry'],sequence:['agar','neon pastel','living seed'],success:'The greenhouse blooms in a color with no name.'},
 researcher:{title:'Rebuild the living question',prompt:'Follow the design-build-test-learn cycle hidden in her phage research.',choices:['design','build','test','learn'],sequence:['design','build','test','learn'],success:'The helix separates and a word floats between its strands.'},
 builder:{title:'Boot the moss terminal',prompt:'SugarCode begins with access. Connect the system from human intent to usable biology.',choices:['plain-language prompt','model and simulate','export for the lab','hide the method'],sequence:['plain-language prompt','model and simulate','export for the lab'],success:'The terminal grows a new branch instead of printing a receipt.'},
 writer:{title:'Open the sentence-door',prompt:'Choose the images in the order they transform control into understanding.',choices:['failed model','boy on water','coffee vortex','cleaner data'],sequence:['failed model','boy on water','coffee vortex'],success:'The library exhales. A sentence steps out from behind its punctuation.'},
 heritage:{title:'Wake the golden loom',prompt:'Weave memory forward: begin with the person, carry the language, then build the keeper.',choices:['grandmother','Tai-Ahom word','Yelon','museum glass'],sequence:['grandmother','Tai-Ahom word','Yelon'],success:'The loom answers in the rhythm of a word spoken back.'}}
function ClueTrial({chapter,onSolved,onClose}){const t=clueTrials[chapter], [picked,setPicked]=useState([]),[shake,setShake]=useState(false);if(!t)return null;function choose(v){const next=[...picked,v];const expected=t.sequence[next.length-1];if(v!==expected){setShake(true);setTimeout(()=>setShake(false),450);setPicked([]);return}setPicked(next);if(next.length===t.sequence.length)setTimeout(onSolved,650)}return <div className="trial-backdrop" role="dialog" aria-modal="true" aria-labelledby="trial-title"><section className={`clue-trial ${shake?'shake':''}`}><button className="trial-x" onClick={onClose} aria-label="Close clue puzzle"><X/></button><p className="eyebrow">A world-specific trial · {picked.length}/{t.sequence.length}</p><h2 id="trial-title">{t.title}</h2><p>{t.prompt}</p><div className="trial-progress">{t.sequence.map((_,i)=><i className={i<picked.length?'on':''} key={i}/>)}</div><div className="trial-choices">{t.choices.map(v=><button disabled={picked.includes(v)} onClick={()=>choose(v)} key={v}>{v}</button>)}</div><small>A wrong choice resets the pattern. Every clue can be solved with keyboard or touch.</small></section></div>}


